\label{q:forget-only-possible}
Is forget-only unlearning always possible? If not, what conditions
make it impossible?

\label{q:memorization-needed}
How much information about the training dataset must the learned model
memorize in order to support future forget-only unlearning requests?

\label{thm:concentration-impossibility}
Fix \(\alpha >1\). Let \(\mathcal{A},\mathcal{\bar{A}}\) be
\(\left({\alpha,\varepsilon}\right)\)-RU for deletion requests of size at most
$m$ and let \(\mathcal{\bar{A}}\) have $(\phi, \Gamma)$-utility on empty
requests. If \(\mathcal{A}\) admits an \((N, m, \Delta, \phi;
\delta_\alpha, \kappa)\)-s.d.e., then it must hold that:

\noindent \textbf{Exact collision} ($\delta_\alpha = 0$):
    \[\varepsilon \geq
        \sup_{r \in R}
        \max \left\{{
            \log N + \frac{1}{\gamma} \log (1 - u(r)),
            \frac{1}{\gamma} \log \frac{N-1}{N} - \log u(r)
        }\right\}.
        \]
\noindent \textbf{Approximate collision} ($\delta_\alpha > 0$):
    \[
        \varepsilon \geq
        \sup_{r \in R}
        \max \left\{{
            \gamma \left({\log N - \delta_\alpha}\right)
            + \frac{1}{\gamma} \log (1 - u(r)),
            \frac{1}{\gamma^2} \log \frac{N-1}{N} - \frac1\gamma \delta_\alpha - \log u(r)
        }\right\},
    \]
where $R \coloneqq \left\{{r \in (0, \Delta/2): 0 < u(r) < 1}\right\}$, $u(r) = \kappa + \Gamma(r)$, and \(\gamma=\frac{\alpha -1}{\alpha}\).

Let \(\mu\) be a common dominating measure for \(P\) and \(Q\), meaning that \(P\) and \(Q\) are both absolutely continuous with respect to \(\mu\): if \(\mu(A)=0\), then \(P(A)=Q(A)=0\). Such a common dominating measure always exists; for example, one may take \(\mu = 1/2(P+Q)\). Define
    \[
    p \coloneqq \frac{dP}{d\mu},
    \qquad
    q \coloneqq \frac{dQ}{d\mu}.
    \]
    The Rényi divergence can be written as,
    \begin{equation}

  D_{\IfNoValueTF{P\,\|\,Q}{\alpha}{P\,\|\,Q}}\!\left( = \right) 
 \frac{1}{\alpha-1} \log \int p(x)^\alpha q(x)^{1-\alpha} d\mu(x).
    \end{equation}
    Define the Radon-Nikodym derivative of $P$ w.r.t. $Q$ as,
    \begin{equation}
        L(x) \coloneqq \frac{dP}{dQ} (x) = \frac{p(x)}{q(x)}.
    \end{equation}
    Then we have,
    \begin{equation}
        \int L(x)^\alpha dQ(x) 
        = \int \left( \frac{p(x)}{q(x)} \right)^\alpha q(x) d\mu(x)
        = \int p(x)^\alpha q(x)^{1 - \alpha} d \mu(x),
    \end{equation}
    which implies that,
    \begin{gather}
    \begin{aligned}

  D_{\IfNoValueTF{P\,\|\,Q}{\alpha}{P\,\|\,Q}}\!\left( = \right) 
 \frac{1}{\alpha-1} & \log \int L(x)^\alpha dQ(x)
        = \frac{1}{\alpha - 1} \log \@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q (L^\alpha)
        \leq \varepsilon \\
        & \implies \@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q (L^\alpha) \leq e^{(\alpha-1)\varepsilon}.
    \end{aligned}
    \end{gather}
    For any event $A$, we have,
    \begin{equation}
        P(A) = \int_A dP(x) = \int_A L(x) \; dQ(x) = \@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q (L \; \mathds{1}_A).
    \end{equation}
    Using  H\"{o}lder's inequality with $m=\alpha$ and $n=\frac{\alpha}{\alpha-1}$ ($\frac{1}{m} + \frac{1}{n} = 1$), we finally get, 
    \begin{gather}
    \begin{aligned}
        P(A)
        &= \@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q (L \; \mathds{1}_A) 
        \leq (\@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q L^m)^{1/m} \; (\@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q \mathds{1}_A^n)^{1/n} \\
        &= (\@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q L^\alpha)^{1/\alpha} \; (\@ifnextchar\bgroup\mathbb{E}\left(\mathbb{E}\right)_Q \mathds{1}_A)^{(\alpha-1)/\alpha}
        \leq e^{(\alpha-1)/\alpha \; \varepsilon} \; Q(A)^{(\alpha-1)/\alpha}.
    \end{aligned}
    \end{gather}
    This completes the proof.

\label{lem:renyi-from-concentration}
    Suppose \(\mathcal{\bar{A}}\) has
    \(\left({\phi,\Gamma}\right)\)-utility on empty requests. 
    Consider two outputs of $\mathcal{A}$: $W_1, W_2$;
    with laws $P_1, P_2$. 
    Fix two disjoint sets $E_1, E_2$ with
    \begin{equation}
    \label{eq:dist-condition}
        \left({
            \forall z_1 \in E_1
        }\right)
        \left({
            \forall z_2 \in E_2
        }\right)
        \quad
        \phi( z_1 - z_2 ) > 2r,
    \end{equation}
    such that
    \(
        \@ifnextchar\bgroup\mathbb{P}\left(\mathbb{P}\right)_{W_i \sim P_i} \left({
            W_i \in E_i
        }\right)
        \geq 1 - \kappa
    \)
    for $i \in \left\{{1,2}\right\}$.
    Define the sets 
    \[
        B_i \coloneqq \left\{{
            w \in \cW: \;
            \left({
                \exists z \in E_i
            }\right)\quad
            \phi(w - z) \leq r
        }\right\},
    \]
    and 
    $Q_i \coloneqq \mathrm{Law} \left({\mathcal{\bar{A}}(W_i, \emptyset)}\right)$ for $i \in \left\{{1,2}\right\}$. Then, it holds that $B_1 \cap B_2 = \emptyset$, and,
    \[
        Q_i (B_i) \geq 
        1 - \kappa - \Gamma(r).
    \]

First, note that $B_1$ and $B_2$ are disjoint. Suppose $y\in B_1\cap B_2$. Then for every $\varepsilon'>0$ there are $w_i\in E_i$ with $\phi(y-w_i)\le r+\varepsilon'$. Hence $\phi(w_1-w_2)\le2r+2\varepsilon'$, which contradicts~\eqref{eq:dist-condition} once $\varepsilon'$ is small enough.

    For $w \in E_i$, the ball
    \(
        \left\{{
            y: \phi(y - w) \leq r
        }\right\}
    \)
    is contained in $B_i$. By~\Cref{def:gamma-utility}, it holds that
    \(
        Q_w (B_i) \geq 1-\Gamma(r)
    \)
    for $i \in \left\{{1,2}\right\}$.
    Integrating over $w \sim P_i$ and keeping only $w \in E_i$, we have,
    \[
    \begin{aligned}
        Q_i(B_i) 
        &\geq
        \int_{E_i} Q_w(B_i) \; P_i(dw)
        \geq \left({
            1 - \Gamma(r)
        }\right)
        \int_{E_i}
        P_i(dw) \\
        &=
        \left({
            1 - \Gamma (r)
        }\right)
        P_i(E_i)
        \geq
        \left({
            1 - \Gamma(r)
        }\right)
        \left({
            1 - \kappa
        }\right)
        \geq
        1 - \kappa - \Gamma(r).
    \end{aligned}
    \]

Since $M \perp\!\!\!\perp (W^K, U^K) \;|\; S$, using the data processing inequality in $(a)$, we have that,
    \begin{gather}
    \label{eq:memorization-main-eq}
    \begin{aligned}
        I(M;S)
        & \overset{(a)}{\geq}
        I(M; W^K, U^K)
        =
        I \left(
            M; (W_{\pi(1)}, U_{\pi(1)}),
                \dots (W_{\pi(K)}, U_{\pi(K)})
        \right) \\
        & \overset{(b)}{=}
        \sum_{i=1}^K
        I \left(
            M; W_{\pi(i)}, U_{\pi(i)} | W_{\pi(<i)}, U_{\pi(<i)}
        \right) \\
        & \overset{(c)}{=}
        \sum_{i=1}^K \left[
            I \left(
                M; U_{\pi(i)} |  W_{\pi(<i)}, U_{\pi(<i)}
            \right)
            +
            I \left(
                M; W_{\pi(i)} |  W_{\pi(<i)}, U_{\pi(<i)}, U_{\pi(i)}
            \right)
        \right] \\
        & \overset{(d)}{\geq}
        \sum_{i=1}^K
        I \left(
            M; W_{\pi(i)} |  W_{\pi(<i)}, U_{\pi(<i)}, U_{\pi(i)}
        \right) \\
        & \overset{(e)}{\geq}
        \sum_{i=1}^K
        I \left(
            \overline{W}_{\pi(i)}; W_{\pi(i)} |  W_{\pi(<i)}, U_{\pi(<i)}, U_{\pi(i)}
        \right),
    \end{aligned}
    \end{gather}
    where $(b)$ and $(c)$ follow from the chain rule of mutual information, while $(d)$ follows from its non-negativity; $(e)$ uses the data processing inequality again: since \(\overline{W}_{\pi(i)}=\mathcal{\bar{A}}(M,U_{\pi(i)})\) is generated from \((M,U_{\pi(i)})\), it holds that
    \(
    \overline{W}_{\pi(i)} \perp\!\!\!\perp W_{\pi(i)} \mid
        (M,  U_{\pi(i)}, W_{\pi(<i)}, U_{\pi(< i)})
    \).
